<template><transition name="sf-toast"><div v-if="open" class="sf-toast" :class="'sf-toast--'+tone" :role="tone==='error'?'alert':'status'" @mouseenter="pause" @mouseleave="schedule" @focusin="pause" @focusout="schedule"><sf-icon :name="tone==='success'?'check':'info'"/><span>{{ message }}</span><button type="button" class="sf-icon-button" aria-label="Dismiss notification" @click="close"><sf-icon name="close" :size="18"/></button></div></transition></template>
<script>
import SfIcon from './SfIcon'
export default {name:'SfToast',components:{SfIcon},model:{prop:'open',event:'input'},props:{open:Boolean,message:{type:String,required:true},tone:{type:String,default:'success'},duration:{type:Number,default:5000}},data(){return {timer:null,remaining:this.duration,timerStarted:0}},watch:{open(value){this.pause();this.remaining=this.duration;if(value)this.schedule()}},mounted(){if(this.open)this.schedule()},beforeDestroy(){this.pause()},methods:{schedule(){if(!this.open||this.duration===0||this.timer)return;this.timerStarted=performance.now();this.timer=setTimeout(this.close,Math.max(0,this.remaining))},pause(){if(this.timer){clearTimeout(this.timer);this.timer=null;this.remaining=Math.max(0,this.remaining-(performance.now()-this.timerStarted))}},close(){this.pause();this.$emit('input',false);this.$emit('dismiss')}}}
</script>
